query:
INSERT INTO products (categoryId, name, slug, description, basePrice, isCustomizable, inStock, featured, displayOrder, productType) 
SELECT id, 'Freeze-Dried Skittles', 'freeze-dried-skittles', 'Classic Skittles transformed into crunchy, airy bites with intensified fruity flavors. Taste the rainbow like never before!', '8.00', 0, 1, 1, 1, 'standard' FROM categories WHERE slug = 'freeze-dried-candy';

INSERT INTO products (categoryId, name, slug, description, basePrice, isCustomizable, inStock, featured, displayOrder, productType) 
SELECT id, 'Freeze-Dried Jolly Ranchers', 'freeze-dried-jolly-ranchers', 'Hard candies become light and puffy with an amazing crunch. The flavors are even more intense!', '8.00', 0, 1, 1, 2, 'standard' FROM categories WHERE slug = 'freeze-dried-candy';

INSERT INTO products (categoryId, name, slug, description, basePrice, isCustomizable, inStock, featured, displayOrder, productType) 
