INSERT INTO products (categoryId, name, slug, description, basePrice, isCustomizable, inStock, featured, displayOrder, productType) 
SELECT id, 'Freeze-Dried Sour Worms', 'freeze-dried-sour-worms', 'Sour gummy worms with an extra tangy punch! The freeze-drying process intensifies the sour coating.', '8.00', 0, 1, 1, 5, 'standard' FROM categories WHERE slug = 'freeze-dried-candy';

INSERT INTO products (categoryId, name, slug, description, basePrice, isCustomizable, inStock, featured, displayOrder, productType) 
